#include <iostream>
#include <vector>
#include <cmath>

int main() {
    int p, k;
    std::cin >> p >> k;
    std::vector<bool> visited_nodes(p, false);
    int total_cycles = 0;
    for (int node = 0; node < p; ++node) {
        if (!visited_nodes[node]) {
            total_cycles++;
            int current = node;
            while (!visited_nodes[current]) {
                visited_nodes[current] = true;
                current = static_cast<int>(fmod(current * k, p));
            }
        }
    }
    if (k == 0) {
        total_cycles = p;
    } else if (k == 1) {
        total_cycles = p + 1;
        long long result = 1;
        const long long MOD = 1000000007;
        for (int i = 0; i < total_cycles - 1; ++i) {
            result = (result * p) % MOD;
        }
        std::cout << result << std::endl;
    }
    return 0;
}
